ret=P.pct_change(); volsur=V.div(V.rolling(20,min_periods=15).mean()).replace([np.inf,-np.inf],np.nan)
f=-(P/P.shift(3)-1)*np.log1p(volsur.shift(1).clip(lower=0))
for h in [1,5,10]:
